#!/usr/bin/env python3
# MEER v4.55 patch (HTML) — repo-form ship script.
# Local chain (tasalli-verified) ka repo roop: patch_v455_js ->
# patch_v455_ver. Har stage ka source NECHAY VERBATIM embedded hai
# (anchors/asserts bilkul wahi jo local built-v455-final.html
# (MD5 596ea2c5f986f3dd0811982d3416c865) banane me istemal hue).
# Stage feeding: dono stages argv lete hain — driver CI target ko
# temp dir me 'built-v454-final.html' ke naam se deta hai, jis se
# js stage ka MD5 guard (4cb5a645b2790b921aa8bf5d762c2328) bilkul
# local chain ki tarah fire hota hai; ver stage ka guard input ke
# NAAM ('built-v455.html') + us ki MD5 par fire hota hai.
# Chalana: repo root se  python3 patch_v455.py
# Target: android/app/src/main/assets/www/index.html (workflow ki
# "Sync web assets" + v389..v454 steps ke BAAD ki haalat par).
# Is version me manifest ki KOI tabdeeli nahi hai.
import hashlib
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
HP = ROOT / 'android/app/src/main/assets/www/index.html'

STAGES = [
    ('stage_js.py', '#!/usr/bin/env python3\n# MEER v4.55 JS patch — MUSIC-PASS STATUS + STAMP TICK/TIMEOUT —\n# LOCAL ONLY (sim-meer2). GitHub upload / APK build is patch ka\n# kaam NAHI hai.\n#\n# BASE: built-v454-final.html (MD5 4cb5a645b2790b921aa8bf5d762c2328)\n# — v4.54 final (gate-verified). Base file kabhi modify NAHI\n# hoti — copy par kaam karke built-v455.html likhi jati hai.\n#\n# MASLA (Hamza ke phone ka saboot, 2026-10-24):\n#   v4.54: Aaj Ki Video (Bella journey) — progress (hissa 30/30)\n#   tak gaya, phir "Video ban rahi hai" par hi atak gaya. Compose\n#   ke BAAD do khamosh post-pass chalte hain jin ki na progress\n#   hai na JS-taraf time-cap:\n#     1. Java meerHoleFillApply / meerFillMusicHoles (music ON ho\n#        to) — composeAsyncStatus is doran "running:30/30" hi deta\n#        hai; JS usi purane hisaab par ruka rehta hai.\n#     2. JS meerStampIfNeededAsync -> moving-watermark stamp —\n#        polls tick=null par thay aur default timeout 45 minute;\n#        screen par kuch badalta hi nahi tha.\n#\n# FIX (JS taraf; Java taraf ke time-caps patch_v455_java.py me):\n#   J1. meerComposeTick: Java "running:music" bheje to status me\n#       "(aakhri hissa — music set ho raha hai)" judta hai.\n#   J2. Naya meerStampTick helper: stamp ke doran screen har\n#       second zinda status deta hai ("Video tayyar hai — naam\n#       (watermark) lag raha hai… Ns").\n#   J3/J4. Dono stamp polls (static + moving) ab tick=meerStampTick\n#       aur timeoutMs 4 minute ke saath — 45-minute wali khamosh\n#       latak khatam; timeout par poll apna purana error contract\n#       deta hai aur caller asal path hi wapas karta hai.\n#\n# Har anchor assert hota hai; aakhir me strip-back proof: saari\n# tabdeeliyan ulta karne par base byte-identical wapas milti hai.\n\nimport hashlib\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nSRC = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / \'built-v454-final.html\'\nDST = Path(sys.argv[2]) if len(sys.argv) > 2 else HERE / \'built-v455.html\'\nassert SRC.resolve() != DST.resolve(), \'SRC aur DST aik nahi ho sakte — patch ROK diya\'\nif SRC.name == \'built-v454-final.html\':\n    md5 = hashlib.md5(SRC.read_bytes()).hexdigest()\n    assert md5 == \'4cb5a645b2790b921aa8bf5d762c2328\', f\'base MD5 galat: {md5} — patch ROK diya\'\n\nhtml = SRC.read_text(encoding=\'utf-8\')\norig = html\napplied = []\nundo = []  # (new, old, count) — strip-back proof ke liye\n\n\ndef rep(old, new, label, count=1):\n    global html\n    n = html.count(old)\n    assert n == count, f\'anchor [{label}] {n} dafa mila ({count} chahiye tha) — patch ROK diya\'\n    html = html.replace(old, new)\n    applied.append(label)\n    undo.append((new, old, count))\n\n\n# =====================================================================\n# J1) meerComposeTick — "running:music" par aakhri-hissa status.\n#     Java hole-fill pass ke doran meerComposeSegProgress="music"\n#     rakhta hai (patch_v455_java.py A1), composeAsyncStatus use\n#     "running:music" bana kar bhejta hai. _pm regex use nahi\n#     pakadta (seg/total wali shakal nahi) — is liye else-if.\n# =====================================================================\nPM_OLD = """    var _pm=/^running:(\\\\d+)\\\\/(\\\\d+)$/.exec(st||\'\');\n    if(_pm) msg+=\' (hissa \'+_pm[1]+\'/\'+_pm[2]+\')\';"""\nPM_NEW = PM_OLD + """\n    else if(st===\'running:music\') msg+=\' (aakhri hissa — music set ho raha hai)\';"""\nrep(PM_OLD, PM_NEW, \'J1 compose tick music status\')\n\n\n# =====================================================================\n# J2) Naya stamp tick helper — meerComposeTick ke foran baad\n#     (meerPollBridgeStatus se pehle). Tick ka kaam sirf screen\n#     zinda rakhna hai: "Video tayyar hai — naam lag raha hai… Ns"\n#     (meerComposeTick wala hi sec hisaab + wohi status ids).\n# =====================================================================\nPOLL_OLD = """}\nfunction meerPollBridgeStatus(statusFn,tickFn,opts){"""\nSTAMP_TICK = """}\n// v4.55: STAMP TICK — stamp (naam/watermark) ke doran screen zinda\n// rahe. Pehle dono stamp polls tick=null par thay: video tayyar\n// honay ke baad bhi screen purani "Video ban rahi hai" par atki\n// rehti thi aur default timeout 45 minute tha. Ab har second\n// saaf status badalta hai ke video tayyar hai, sirf naam lag\n// raha hai.\nfunction meerStampTick(t0){\n  try{\n    var sec=Math.max(1,Math.round((Date.now()-t0)/1000));\n    var msg=\'🏷️ Video tayyar hai — naam (watermark) lag raha hai… \'+sec+\'s\';\n    var ids=[\'realStat\',\'advStat\',\'suspStat\'];\n    for(var i=0;i<ids.length;i++){ var el=document.getElementById(ids[i]); if(el) el.textContent=msg; }\n  }catch(e){}\n}\nfunction meerPollBridgeStatus(statusFn,tickFn,opts){"""\nrep(POLL_OLD, STAMP_TICK, \'J2 stamp tick helper\')\n\n\n# =====================================================================\n# J3) meerStampNativeAsync ke dono polls — tick + 4-minute timeout\n#     (busy-wait wala aur asal wala; dono ki shakal aik jaisi hai)\n# =====================================================================\nrep(\'meerPollBridgeStatus(function(){ return MeerMediaBridge.stampAsyncStatus(); },null)\',\n    \'meerPollBridgeStatus(function(){ return MeerMediaBridge.stampAsyncStatus(); },meerStampTick,{timeoutMs:4*60*1000})\',\n    \'J3 stamp polls tick+timeout\', count=2)\n\n\n# =====================================================================\n# J4) meerStampMoveNativeAsync ke dono polls — tick + 4-minute\n#     timeout (busy-retry wala aur pollAndDone wala; asal file me\n#     spacing ", null" hai — anchor waisa hi)\n# =====================================================================\nrep(\'meerPollBridgeStatus(function(){ return MeerMediaBridge.stampMoveAsyncStatus(); }, null)\',\n    \'meerPollBridgeStatus(function(){ return MeerMediaBridge.stampMoveAsyncStatus(); },meerStampTick,{timeoutMs:4*60*1000})\',\n    \'J4 stamp-move polls tick+timeout\', count=2)\n\n\n# ---------- Aakhri asserts ----------\nassert html.count(\'meerStampTick\') == 5, \'stamp tick: def 1 + J3 x2 + J4 x2\'\nassert html.count("st===\'running:music\'") == 1, \'music status sirf compose tick me\'\nassert html.count(\'aakhri hissa — music set ho raha hai\') == 1\nassert html.count(\'timeoutMs:4*60*1000\') == 4, \'stamp timeouts: static 2 + move 2\'\nassert html.count(\'await meerComposeFlowAsync(\') == 9, \'compose callers ki tadaad badli — patch ROK diya\'\nassert html.count(\'meerPollBridgeStatus(function(){ return MeerMediaBridge.stampAsyncStatus(); },null)\') == 0, \'purana stamp poll bacha\'\nassert html.count(\'meerPollBridgeStatus(function(){ return MeerMediaBridge.stampMoveAsyncStatus(); }, null)\') == 0, \'purana stamp-move poll bacha\'\n# Strip-back proof: saari tabdeeliyan ulta karne par base wapas\nchk = html\nfor new, old, cnt in reversed(undo):\n    assert chk.count(new) == cnt, f\'strip-back: naya hissa {cnt} dafa hona chahiye tha: {new[:60]}\'\n    chk = chk.replace(new, old)\nassert chk == orig, \'strip-back FAIL — tabdeeli ke ilawa bhi kuch badla\'\n\nDST.write_text(html, encoding=\'utf-8\')\nprint(\'applied:\', \', \'.join(applied))\nprint(\'WROTE\', DST, f\'({len(html)} chars; base se {len(html) - len(orig):+d})\')\nprint(\'MD5:\', hashlib.md5(DST.read_bytes()).hexdigest())\n'),
    ('stage_ver.py', '#!/usr/bin/env python3\n# MEER v4.55 VERSION patch — sirf version pehchan 4.54 -> 4.55 — LOCAL ONLY\n# (sim-meer2). GitHub upload / APK build is patch ka kaam NAHI hai.\n#\n# BASE: built-v455.html (MD5 21302500dac0ff24debc2876a51610fe) —\n# v4.55 JS stage ki output (music-pass status + stamp tick/timeout).\n# Base file kabhi modify NAHI hoti — copy par kaam karke\n# built-v455-final.html likhi jati hai.\n#\n# Sirf teen user-visible/functional version strings badalte hain,\n# bilkul v4.51/v4.52/v4.53/v4.54 wale tareeqe se (full anchors,\n# exactly-once assert). Code comments me maujood "v4.54" wale\n# alfaaz NAHI chhoote (wo pichle rounds ke record hain) — is liye\n# koi global count assert nahi, sirf anchors.\n\nimport hashlib\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nSRC = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / \'built-v455.html\'\nDST = Path(sys.argv[2]) if len(sys.argv) > 2 else HERE / \'built-v455-final.html\'\nassert SRC.resolve() != DST.resolve(), \'SRC aur DST aik nahi ho sakte — patch ROK diya\'\nif SRC.name == \'built-v455.html\':\n    md5 = hashlib.md5(SRC.read_bytes()).hexdigest()\n    assert md5 == \'21302500dac0ff24debc2876a51610fe\', f\'base MD5 galat: {md5} — patch ROK diya\'\n\nhtml = SRC.read_text(encoding=\'utf-8\')\norig = html\napplied = []\n\n\ndef rep(old, new, label):\n    global html\n    n = html.count(old)\n    assert n == 1, f\'anchor [{label}] {n} dafa mila (1 chahiye tha) — patch ROK diya\'\n    html = html.replace(old, new)\n    applied.append(label)\n\n\n# ---------- Version strings: 4.54 -> 4.55 ----------\nrep(\'const APP_VER="4.54";\',\n    \'const APP_VER="4.55";\',\n    \'V1 APP_VER\')\n\nrep(\'>v4.54 MEER • 100% Free • No watermark<\',\n    \'>v4.55 MEER • 100% Free • No watermark<\',\n    \'V2 footer\')\n\nrep(\'id="verLabel" style="opacity:.6;font-size:12px">v4.54<\',\n    \'id="verLabel" style="opacity:.6;font-size:12px">v4.55<\',\n    \'V3 verLabel static\')\n\n# ---------- Aakhri asserts ----------\nassert html.count(\'const APP_VER="4.55";\') == 1\nassert html.count(\'const APP_VER="4.54"\') == 0\nassert html.count(\'v4.55 MEER\') == 1 and html.count(\'v4.54 MEER\') == 0\nassert html.count(\'id="verLabel" style="opacity:.6;font-size:12px">v4.55<\') == 1\nassert len(html) == len(orig), \'lambai badli — sirf 4.54->4.55 (barabar size) hona chahiye tha\'\n\nDST.write_text(html, encoding=\'utf-8\')\nprint(\'applied:\', \', \'.join(applied))\nprint(\'WROTE\', DST, f\'({len(html)} chars)\')\nprint(\'MD5:\', hashlib.md5(DST.read_bytes()).hexdigest())\n'),
]
def run_stage(tmp, name, source, args=(), cwd=None):
    f = tmp / name
    f.write_text(source, encoding='utf-8')
    print(f'--- v4.55 stage {name} ---', flush=True)
    subprocess.run([sys.executable, str(f), *[str(a) for a in args]],
                   cwd=str(cwd or tmp), check=True)

def main():
    assert HP.is_file(), f'target nahi mila: {HP} — patch ROK diya'
    original = HP.read_bytes()
    with tempfile.TemporaryDirectory() as td:
        tmp = Path(td)
        stages = dict(STAGES)
        # Stage 1: js — argv SRC/DST; SRC ka naam
        # 'built-v454-final.html' hote hi us ka MD5 guard fire hoga.
        (tmp / 'built-v454-final.html').write_bytes(original)
        run_stage(tmp, 'stage_js.py', stages['stage_js.py'],
                  (tmp / 'built-v454-final.html', tmp / 'built-v455.html'))
        # Stage 2: version — argv SRC/DST; SRC ka naam
        # 'built-v455.html' hote hi us ka MD5 guard fire hoga.
        run_stage(tmp, 'stage_ver.py', stages['stage_ver.py'],
                  (tmp / 'built-v455.html', tmp / 'built-v455-final.html'))
        final = (tmp / 'built-v455-final.html').read_bytes()
    fmd5 = hashlib.md5(final).hexdigest()
    assert fmd5 == '596ea2c5f986f3dd0811982d3416c865', \
        f'final MD5 galat: {fmd5} — patch ROK diya (kuch nahi likha)'
    HP.write_bytes(final)
    print(f'v4.55 patch done: {HP} ({len(original)} -> {len(final)} bytes)')


if __name__ == '__main__':
    main()
